import primitive_api as api
import json

def short(obj, limit=2500):
    try:
        s = json.dumps(obj, indent=1, default=str)
    except Exception:
        s = str(obj)
    return s[:limit]

print("== TASK CONTEXT ==")
ctx = api.get_task_context()
print(short(ctx, 1200))

print("\n== INITIAL SUCCESS ==")
print(short(api.check_activity_success(), 800))

for scope in ["phone", "living", "character"]:
    print(f"\n== SYMBOLIC STATE SCOPE: {scope} ==")
    try:
        print(short(api.query_symbolic_state(scope=scope), 2500))
    except Exception as e:
        print("query error:", e)

print("\n== EXECUTABLE ACTION PROBES ==")
for q in ["walk", "find", "grab", "phone", "living"]:
    try:
        acts = api.list_executable_actions(query=q, limit=25)
        print(f"-- {q}: {len(acts)}")
        for a in acts:
            print(" ", a)
    except Exception as e:
        print(f"executable probe error for {q}:", e)

